    out = [row[:] for row in grid]
    seen = set()
    candidates = []

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            wall = perimeter = 0

            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if not (0 <= ny < h and 0 <= nx < w):
                        perimeter += 1
                    elif grid[ny][nx] == 5:
                        wall += 1
                        perimeter += 1
                    elif (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))

            # Keep the zero regions substantially outlined by 5s, rather
            # than the broad open background regions.
            if wall and wall / perimeter >= 0.5:
                candidates.append(cells)

    if candidates:
        smallest = min(candidates, key=len)
        largest = max(candidates, key=len)
        for r, c in smallest:
            out[r][c] = 7
        for r, c in largest:
            out[r][c] = 8

    return out
